  $('#presence-takeover')?.querySelector('button')?.addEventListener('click',()=>run(async()=>{W.setActive(false);const fresh=await api('session');render(fresh);if(presence)presence.takeover();else connectPresence();$('#presence-takeover').hidden=true;}));
  $('#record-start').onclick=()=>{if(!W.canvas.captureStream||!window.MediaRecorder){$('#record-note').textContent='此瀏覽器不支援畫布錄影；請使用桌機 Chrome／Safari。';return;}chunks=[];const stream=W.canvas.captureStream(24),type=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,type?{mimeType:type}:{});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));const a=$('#record-download');a.href=recordUrl;a.download='city-v42-live-3d.'+(recorder.mimeType.includes('mp4')?'mp4':'webm');a.hidden=false;$('#record-note').textContent='影片已就緒，包含室外／室內實際 3D 畫布。';};recorder.start();$('#record-start').disabled=true;$('#record-stop').disabled=false;$('#record-download').hidden=true;$('#record-note').textContent='正在錄製實際 3D 畫布。完成操作後回這裡停止。';$('#help').close();W.notify('開始錄製 3D 操作');};
  $('#record-stop').onclick=()=>{if(recorder?.state==='recording')recorder.stop();$('#record-start').disabled=false;$('#record-stop').disabled=true;};
  window.addEventListener('cozy-social-action',e=>{if(e.detail.peer){if(!state||!presence?.sendInteraction({type:'interactionRequest',targetId:e.detail.targetId,kind:e.detail.kind}))W.notify('請先連線再互動。');}else W.performNpcSocial(e.detail.targetId,e.detail.kind);});
  let supervisorStarting=false,supervisorDialog=null;
  window.addEventListener('city-supervisor-find',()=>{if(!mustLogin())return;window.CityUI?.setOpen(false);W.notify('蔚榮主管在戶外巡走，走近就能聊聊。');});
  window.addEventListener('city-supervisor-arrived',async()=>{
    if(supervisorStarting||supervisorDialog?.open||!state)return;supervisorStarting=true;const epoch=generation,uid=state.profile.id;
    try{
      // Flush the last normal walking pose before the distance check.
      presence?.sendPose();const start=await api('supervisor/start',{requestId:requestId()});if(epoch!==generation||state?.profile.id!==uid)return;
      const encounter=start.encounter;W.setSupervisor?.(start.supervisor);W.setActive(false);window.CityUI?.setOpen(false);if($('#journal').open)$('#journal').close();
      const dialog=make('dialog');dialog.id='supervisor-talk';dialog.setAttribute('aria-label','與蔚榮主管聊天');supervisorDialog=dialog;const close=make('button','×');close.className='close';close.setAttribute('aria-label','結束主管聊天');close.onclick=()=>dialog.close();
      const heading=make('h2','蔚榮主管'),intro=make('p','小城遊戲分身 · 回答九店位置、遊戲規則與你自己的遊戲資產；每則回答附依據。'),transcript=make('div');transcript.className='supervisor-transcript';transcript.setAttribute('aria-live','polite');
      const welcome=make('p','一起慢慢逛吧。今天想知道哪家門市、哪個任務，或想買什麼布置？');welcome.className='supervisor-response';transcript.append(welcome);
      const form=make('form'),label=make('label','想問蔚榮主管的事'),input=make('textarea');input.maxLength=500;input.required=true;input.rows=2;input.placeholder='例如：三創在哪裡？我買得起哪些家具？';label.append(input);const send=make('button','送出問題');send.type='submit';send.className='primary';form.append(label,send);
      const feedback=make('p');feedback.className='supervisor-feedback';feedback.setAttribute('role','status');const complete=make('button');complete.type='button';complete.className='primary';
      const finishId=requestId(),expiresAt=performance.now()+Math.max(0,encounter.expires-encounter.serverTime);let readyAt=Infinity,answered=false,busy=false,finished=false;
      const current=()=>dialog.open&&epoch===generation&&state?.profile.id===uid;
      function paint(){const remaining=Math.max(0,Math.ceil((readyAt-performance.now())/1000));complete.textContent=finished?'今天的交流已完成':performance.now()>=expiresAt?'聊天已到時間':!answered?'提問後可完成今日交流':remaining?'讀完回答，再等 '+remaining+' 秒':encounter.eligible?'完成交流 · 領 5 金幣':'完成交流 · 今天已領過';complete.disabled=finished||busy||!answered||remaining>0||performance.now()>=expiresAt;send.disabled=busy||finished||performance.now()>=expiresAt;}
      form.onsubmit=async event=>{event.preventDefault();if(busy||!current()||!input.value.trim())return;busy=true;feedback.textContent='主管正在查閱小城資料…';paint();const question=input.value.trim();try{const response=await api('supervisor/ask',{encounterId:encounter.id,question});if(!current())return;const q=make('p',question);q.className='supervisor-question';const answer=make('div');answer.className='supervisor-response';answer.append(make('p',response.answer));if(response.sources?.length){const details=make('details');details.append(make('summary','查看回答依據（'+response.sources.length+'）'));for(const source of response.sources){const section=make('p');section.append(make('strong',source.title),make('span',' — '+source.excerpt));if(source.url?.startsWith('https://')){const link=make('a',' 查看來源 ↗');link.href=source.url;link.target='_blank';link.rel='noopener';section.append(link);}details.append(section);}answer.append(details);}transcript.append(q,answer);transcript.scrollTop=transcript.scrollHeight;input.value='';answered=answered||response.supported;if(response.encounter.readyAt)readyAt=performance.now()+Math.max(0,response.encounter.readyAt-response.encounter.serverTime);feedback.textContent=response.supported?'已依已確認的小城資料回答。':'目前沒有足夠依據；可換問門市、任務、金幣或家具。';}catch(error){if(current())feedback.textContent=error.message;}finally{busy=false;if(current())paint();}};
      complete.onclick=async()=>{if(complete.disabled||!current())return;busy=true;paint();feedback.textContent='正在保存今天的交流…';try{const response=await api('supervisor/complete',{encounterId:encounter.id,requestId:finishId});if(!current())return;render(response);finished=true;feedback.textContent=response.receipt.coins?'已保存，遊戲錢包增加 '+response.receipt.coins+' 金幣。':'今天已領過，這次聊天沒有重複發獎。';close.textContent='回到街區';}catch(error){if(current())feedback.textContent=error.message;}finally{busy=false;if(current())paint();}};
      dialog.append(close,heading,intro,transcript,form,feedback,complete);document.body.append(dialog);dialog.showModal();input.focus();paint();const ticker=setInterval(paint,250);
      dialog.addEventListener('close',()=>{clearInterval(ticker);dialog.remove();if(supervisorDialog===dialog)supervisorDialog=null;if(epoch===generation&&state?.profile.id===uid){api('supervisor/end',{encounterId:encounter.id}).catch(()=>{});W.setActive(!!presence?.getState().connected&&!presence?.getState().replaced);}}, {once:true});
    }catch(error){if(epoch===generation)W.notify(error.message);}finally{supervisorStarting=false;}
  });
  window.addEventListener('cozy-waypoint',()=>presence?.sendPose());window.addEventListener('cozy-scene',()=>{currentWork=null;presence?.sendPose();});document.addEventListener('visibilitychange',()=>{if(document.hidden){recovery.pause();W.setActive(false);presence?.close({suspend:true,sendLastPose:true});}else resumeSession();});window.addEventListener('pagehide',()=>{recovery.pause();W.setActive(false);presence?.close({suspend:true,sendLastPose:true});});window.addEventListener('pageshow',()=>{if(!document.hidden)resumeSession();});
  (async()=>{const hash=new URLSearchParams(location.hash.slice(1)),invite=hash.get('invite');if(invite){history.replaceState(null,'',location.pathname);try{await loginDemo({oneTime:invite});W.notify('歡迎來到你的小城。');connectPresence();}catch(error){if(error.code==='INVITE_EXPIRED'||!error.status){await recovery.restore({force:true});if(!state)message('邀請已使用或過期；若此瀏覽器曾登入，網路恢復後會自動讀取。');}else message(error.message);}}else{await recovery.restore();if(!state&&!window.CityEmployeePlay&&sessionFailure==='AUTH_REQUIRED'&&!new URLSearchParams(location.search).has('continue'))await window.GuestAccess?.startAutomatic?.({sessionErrorCode:sessionFailure});}})().finally(()=>{booting=false;if(!state)W.setActive(true);});
